use std::{is_email, is_some, str_len, trim}

table users: User key email

type User {
  email: String,
  name: String,
  password_hash: String,
  id: String,
  phone: Option[String],
}

type Signup {
  email: String,
  name: String,
  password: String,
  phone: String,
}

type Profile {
  email: String,
  name: String,
  phone: Option[String],
}

type UserError =
  | Taken(email: String)
  | BadLogin

api fn signup(input: Signup) -> Result[Profile, UserError]
  route: POST "/users"
  effects: rand, store(users)
  requires: is_email(input.email) && str_len(trim(input.name)) > 0 && str_len(input.password) >= 8 && is_phone(input.phone)
{
  if is_some(get(users, input.email)) {
    return Err(Taken(input.email))
  }
  let user = User {
    email: input.email,
    name: trim(input.name),
    password_hash: hash_password(input.password),
    id: uuid(),
    phone: Some(trim(input.phone)),
  }
  insert(users, user)
  return Ok(profile(user))
}

fn profile(u: User) -> Profile {
  return Profile { email: u.email, name: u.name, phone: u.phone }
}

fn is_phone(phone: String) -> Bool {
  return match phone {
    "" => false,
    p if p.starts_with('+') && str_len(p) >= 8 && str_len(p) <= 16 && p[1..].chars().all(|c| c >= '0' && c <= '9') => true,
    _ => false,
  }
}

api fn login(input: Signup) -> Result[Profile, UserError]
  route: POST "/login"
  effects: store(users)
{
  return match get(users, input.email) {
    Some(u) => match verify_password(input.password, u.password_hash) {
      true => Ok(profile(u)),
      false => Err(BadLogin),
    },
    None => Err(BadLogin),
  }
}
</write>

