  save(products, p)
  return Ok(rating_summary(p))
}

api fn get_rating(sku: String) -> Result[RatingSummary, RatingError]
  route: GET "/products/{sku}/rating"
  effects: store(products)
{
  return match get(products, sku) {
    Some(p) => Ok(rating_summary(p)),
    None => Err(Missing(sku)),
  }
}

type Rating {
  sku: String,
  stars: Int,
}

type RatingSummary {
  sku: String,
  count: Int,
  average: Float,
}

fn rating_summary(p: Product) -> RatingSummary {
  let count = len(p.ratings)
  let total = sum(map(p.ratings, |r| r.stars))
  let average = match count {
    0 => null,
    _ => to_float(total) / to_float(count),
  }
  return RatingSummary { sku: p.sku, count: count, average: average }
}

type RatingError =
  | Missing(sku: String)
