    Some(u) => u,
    None => return Err(NoSuchUser(current_email)),
  }
  let updated_user = User { email: new_email, name: user.name, password_hash: user.password_hash, id: user.id }
  save(users, updated_user)
  return Ok(profile(updated_user))
}
