"""Discounts: applying percentage off codes to open orders."""

import json
import sqlite3
from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException
from pydantic import TypeAdapter

from .db import transaction
from .errors import ApiError, InvalidRequest
from .schemas import Discount, Order, Status


router = APIRouter()

_discount = TypeAdapter[Discount](Discount)


def row_to_discount(row: sqlite3.Row) -> Discount:
    return Discount(
        code=row["code"],
        percent=row["percent"],
    )


def find_discount(conn: sqlite3.Connection, code: str) -> Discount | None:
    row = conn.execute("SELECT * FROM discounts WHERE code = ?", (code,)).fetchone()
    return row_to_discount(row) if row else None


def all_discounts(conn: sqlite3.Connection) -> list[Discount]:
    return [row_to_discount(r) for r in conn.execute("SELECT * FROM discounts ORDER BY code")]


def save_discount(conn: sqlite3.Connection, discount: Discount) -> None:
    conn.execute(
        "INSERT OR REPLACE INTO discounts (code, percent) VALUES (?, ?)",
        (discount.code, discount.percent),
    )


@router.post("/discounts")
def add_discount(body: Discount) -> Discount:
    if len(body.code) < 3 or not 1 <= body.percent <= 100:
        raise InvalidRequest("the code has at least 3 characters, and percent is between 1 and 100")
    with transaction() as conn:
        if find_discount(conn, body.code):
            raise ApiError("Invalid", reason=f"duplicate code {body.code}")
        save_discount(conn, body)
    return body


@router.post("/orders/{id}/discount")
def apply_discount(
    id: int,
    body: Discount,
    payments: Annotated[PaymentClient, Depends(get_payments)],
) -> Order:
    with transaction() as conn:
        row = conn.execute("SELECT * FROM orders WHERE id = ?", (id,)).fetchone()
        if row is None:
            raise ApiError("Missing", sku=f"order {id}")
        order = Order(
            id=row["id"],
            email=row["email"],
            lines=[Line.model_validate(x) for x in json.loads(row["lines"])],
            total=row["total"],
            status=_status.validate_json(row["status"]),
        )
        if not isinstance(order.status, Status.Open):
            raise ApiError("Invalid", reason=f"order {id} is not open")
        discount = find_discount(conn, body.code)
        if discount is None:
            raise ApiError("UnknownCode", code=body.code)
        new_total = order.total - (order.total * discount.percent // 100)
        paid = order.model_copy(update={"total": new_total, "status": Paid(receipt=payments.charge(new_total))})
        save_order(conn, paid)
    return paid
</write>

<write path="backend/shop/db.py">
"""SQLite storage. The database file is $SHOP_DATABASE (default shop.db)."""

import os
import sqlite3
import threading
from collections.abc import Iterator
from contextlib import contextmanager

SCHEMA = """
CREATE TABLE IF NOT EXISTS products (
    pos INTEGER PRIMARY KEY AUTOINCREMENT,
    sku TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    cents INTEGER NOT NULL,
    stock INTEGER NOT NULL,
    tags TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS users (
    pos INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    password_hash TEXT NOT NULL,
    id TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS orders (
    id INTEGER PRIMARY KEY,
    email TEXT NOT NULL,
    lines TEXT NOT NULL,
    total INTEGER NOT NULL,
    status TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS discounts (
    code TEXT NOT NULL UNIQUE,
    percent INTEGER NOT NULL
);
"""

_lock = threading.RLock()
_connection: sqlite3.Connection | None = None


def _connect() -> sqlite3.Connection:
    global _connection
    if _connection is None:
        path = os.environ.get("SHOP_DATABASE", "shop.db")
        _connection = sqlite3.connect(path, check_same_thread=False)
        _connection.row_factory = sqlite3.Row
        _connection.executescript(SCHEMA)
    return _connection


@contextmanager
def transaction() -> Iterator[sqlite3.Connection]:
    """A connection for one unit of work, committed at the end."""
    with _lock:
        conn = _connect()
        with conn:
            yield conn


def reset() -> None:
    """Close the database; the next request opens $SHOP_DATABASE again."""
    global _connection
    with _lock:
        if _connection is not None:
            _connection.close()
        _connection = None
</write>

